    r_landmark_title: "Wenshu Monastery → Wuhou Shrine: Classic City Landmark Ride", r_landmark_dist: "15-18 km", r_landmark_time: "~2-3h (with stops)", r_landmark_badge: "City Landmarks", r_landmark_search: "Search \"成都经典景点骑行路线\"",
    r_landmark_route: "<strong>Route:</strong> Wenshu Monastery → Chenghua Park → Chengdu 339 (TV Tower) → Dongfeng Bridge → Chunxi Road → Tianfu Square → People's Park → Kuanzhai Alley → Qintai Road → Qingyang Palace → Du Fu Thatched Cottage → Huanhuaxi Park → Wuhou Shrine (13 iconic landmarks)",
    r_landmark_why: "<strong>Why this route:</strong> The ultimate Chengdu city highlight ride — every stop is a must-visit landmark. Start from the Buddhist tranquility of Wenshu Monastery, pass through the neon-lit 339 TV Tower, shop at Chunxi Road, stroll the historic Kuanzhai Alley, pay homage to the poet Du Fu, and end at the legendary Wuhou Shrine. Ride any section you like — you don't need to complete the entire route!",
    r1_title: "Chengdu East Gate Riverside Loop", r1_dist: "8-12 km", r1_time: "~1h", r1_badge: "City Riverside", r1_search: "Search \"成都东门沿河小环线\"",
    r1_route: "<strong>Route:</strong> Dongmen Bridge → Hejiang Pavilion → Anshun Bridge → Jiuyan Bridge → Wangjiang Pavilion → Donghu Park → Dongli Emerald Lake → Shahe Greenway → Tazishan Park → Shuanggui Park → Duobao Temple → Xinhua Park → Living Water Park → Return to Dongmen Bridge (13 nodes)",
    r1_why: "<strong>Why this route:</strong> A compact urban loop following Chengdu's eastern river system, weaving through 13 scenic nodes including historic bridges, parks, and temples. Perfect for a relaxed afternoon ride.",
    r2_title: "Central City River Grand Loop", r2_dist: "40.90 km", r2_time: "~4h17min", r2_badge: "City Riverside", r2_search: "Search \"成都城中沿河大环线\"",
    r2_route: "<strong>Route:</strong> Shahe → Fuhe → Nanhe loop, connecting Chengdu's central city water systems",
    r2_why: "<strong>Why this route:</strong> A scenic grand loop tracing Chengdu's three major urban rivers. At 40.9 km with an average speed of 9.55 km/h, it's a relaxed sightseeing ride through the heart of the city's waterways.",
    r3_title: "Jinjiang & Ring Greenway Interchange Loop", r3_dist: "15-25 km", r3_time: "~2-3h", r3_badge: "City Riverside", r3_search: "Search \"锦江绕城绿道互通环线\"",
    r3_route: "<strong>Route:</strong> Donghu Park → Jincheng Park → Zhonghe Wetland Park (10 park nodes, greenway interchange)",
    r3_why: "<strong>Why this route:</strong> Seamlessly connects the Jinjiang Greenway with the Ring Greenway, passing through 10 park nodes. A flexible route where you can choose sections from 15 to 25 km.",
    r4_title: "Ring Greenway SE: Qinglong Lake - Bai Lu Wan Wetland", r4_dist: "15.12 km", r4_time: "~1.5h", r4_badge: "Wetland Ecology",
    r4_route: "<strong>Route:</strong> Qinglong Lake Wetland Park → Yushi Wetland Park → Huatian Wetland → Bai Lu Wan Wetland Park",
    r4_why: "<strong>Why this route:</strong> A gentle 15 km ride through four distinct wetland ecosystems on the southeastern section of Chengdu's Ring Greenway. Birdwatcher's paradise with rich biodiversity.",
    r5_title: "Xuyan River - Baitiao River Greenway", r5_dist: "~7 km", r5_time: "~1h", r5_badge: "Wetland Ecology", r5_search: "Search \"徐堰河柏条河绿道\"",
    r5_route: "<strong>Route:</strong> 5 wetland ecological nodes along Xuyan River and Baitiao River in Sandao Yan, Pidu District — includes Chengdu's first \"Sky Greenway\" (3.5m wide elevated cycling path)",
    r5_why: "<strong>Why this route:</strong> A compact 7 km ride featuring Chengdu's first elevated \"Sky Greenway\" — a 3.5-meter-wide cycling path suspended above the wetlands.",
