    r6_route: "<strong>Route:</strong> Jincheng Lake Park → Yuedong Cailin (Colorful Forest) → Mengchong Paradise (Pet Park) → International Intangible Cultural Heritage Expo Park",
    r6_why: "<strong>Why this route:</strong> A 24 km ride through the southwestern section of the Ring Greenway, featuring the colorful forest, a pet-friendly park, and culminating at the UNESCO Intangible Cultural Heritage Expo Park.",
    r7_title: "Qinglong Lake - Dongfeng Canal - Dong'an Lake", r7_dist: "~30 km", r7_time: "~3h", r7_badge: "New District Park", r7_search: "Search \"青龙湖东安湖骑行\"",
    r7_route: "<strong>Route:</strong> Qinglong Lake Wetland Park → Dongfeng Canal Greenway → Dong'an Lake Sports Park → Yimahe Park Phase II → Longquanshan Urban Forest Park",
    r7_why: "<strong>Why this route:</strong> A 30 km journey from the wetland tranquility of Qinglong Lake to the Olympic-standard Dong'an Lake Sports Park, finishing at the foothills of Longquan Mountain.",
    r8_title: "Tianfu New District Greenway Loop (Luxi River & Tianfu Park)", r8_dist: "40.99 km", r8_time: "~3.5h", r8_badge: "New District Park",
    r8_route: "<strong>Route:</strong> Luxi River Ecological Zone → Tianfu Park → Xinglong Lake → Science City",
    r8_why: "<strong>Why this route:</strong> A 41 km loop through Chengdu's futuristic Tianfu New District. Ride past the tech hub of Science City, the serene Xinglong Lake, and the lush Luxi River ecological corridor. 294m elevation gain.",
    r9_title: "Xinjin Riverside Greenway", r9_dist: "29 km", r9_time: "~2.5h", r9_badge: "Countryside Greenway",
    r9_route: "<strong>Route:</strong> Xinjin Nanhe River greenway — entirely flat, zero elevation gain",
    r9_why: "<strong>Why this route:</strong> A 29 km riverside cruise with zero climbing — the flattest route in the collection. Perfect for recovery rides, family outings, or anyone who wants to enjoy the countryside without breaking a sweat.",
