    r12_title: "Wenjiang Greenway Grand Loop: Beilin Greenway", r12_dist: "52.51 km", r12_time: "~4h45min", r12_badge: "Countryside Greenway", r12_search: "Search \"温江北林绿道\"",
    r12_route: "<strong>Route:</strong> Wenjiang Beilin Greenway Grand Loop, through Wenjiang's pastoral countryside",
    r12_why: "<strong>Why this route:</strong> The longest countryside route at 52.5 km with 463m elevation gain. A true intermediate challenge through Wenjiang's northern forest greenway, offering expansive farmland views and bamboo groves.",
    r13_title: "Jinjiang Greenway: Shuxiu Park - Dujiangyan", r13_dist: "58.52 km", r13_time: "~6h13min", r13_badge: "Long Distance Challenge", r13_search: "Search \"锦江绿道蜀绣到都江堰\"",
    r13_route: "<strong>Route:</strong> Shuxiu Park → Jinjiang Greenway North Section → Dujiangyan Scenic Area, following the Jinjiang River upstream",
    r13_why: "<strong>Why this route:</strong> The ultimate challenge — a 58.5 km ride tracing the Jinjiang River upstream from Shuxiu Park to the UNESCO World Heritage Dujiangyan Irrigation System. Ride through history, from the plains of Chengdu to the foothills of the Tibetan Plateau.",
