    metro_bike_title: "Metro + Shared Bike: The Ultimate Chengdu Combo", metro_bike_desc: "Chengdu's metro network spans 14+ lines covering the entire city. Take the metro to skip the heat and traffic, then hop on a shared bike right at the station exit to reach your destination's doorstep. The perfect summer strategy!", metro_step1_title: "Step 1: Ride Metro", metro_step1_desc: "Take the air-conditioned metro to skip the hot streets. Chengdu metro covers all major areas.", metro_step2_title: "Step 2: Grab a Bike", metro_step2_desc: "Scan a shared bike right outside the station. Meituan / Hello / Qingju bikes are everywhere.", metro_step3_title: "Step 3: Arrive Fresh", metro_step3_desc: "Ride the last 1–3 km to the scenic spot entrance. No sweating, no parking hassle!", metro_tip1: '❄️ <strong style="color:var(--ink);">AC Escape:</strong> Metro cars are fully air-conditioned — the coolest way to cross the city in summer (30–35°C outside!)', metro_tip2: '💳 <strong style="color:var(--ink);">One App for All:</strong> Alipay QR code works for both metro gates and shared bikes — no separate tickets needed', metro_tip3: '🗺 <strong style="color:var(--ink);">Bikes at Every Exit:</strong> Metro stations in Chengdu always have shared bikes parked at exits A–D — never walk far', metro_tip4: '🌳 <strong style="color:var(--ink);">Greenway Stations:</strong> Lines 1, 5, 6, 18 all connect to Tianfu Greenway hubs — bike straight from the station onto the greenway!', metro_tip5: '🕐 <strong style="color:var(--ink);">Metro Hours:</strong> 6:00–23:30 daily. Plan your return — last train varies by line and station', metro_tip6: '💡 <strong style="color:var(--ink);">Pro Move:</strong> Metro to the edge of the city → bike into the countryside. Best of both worlds — comfort + adventure!',
