    theme1_title: "城市沿河骑行", theme2_title: "湿地生态骑行", theme3_title: "新区公园环线", theme4_title: "乡村绿道骑行", theme5_title: "长途挑战骑行", theme6_title: "特色主题骑行",
    diff_beginner: "入门休闲", diff_beginner_plus: "初级进阶级", diff_intermediate: "中级", diff_advanced: "中高级",
