    r_landmark_title: "文殊院→武侯祠：经典城中景点骑行路线", r_landmark_dist: "15-18 km", r_landmark_time: "约2-3小时（含停留）", r_landmark_badge: "城中景点", r_landmark_search: "搜索\"成都经典景点骑行路线\"",
    r_landmark_route: "<strong>路线：</strong>文殊院→成华公园→成都339→东风桥→春熙路→天府广场→人民公园→宽窄巷子→琴台路→青羊宫→杜甫草堂→浣花溪公园→武侯祠（13个经典地标）",
    r_landmark_why: "<strong>推荐理由：</strong>成都城市精华骑行路线，每一站都是必打卡地标。从文殊院的佛门清幽出发，途经霓虹闪耀的339电视塔，逛春熙路购物，漫步宽窄巷子，拜谒诗圣杜甫草堂，最终抵达武侯祠。可任选段落骑行，无需全程骑完！",
    r1_title: "成都东门沿河小环线", r1_dist: "8-12 km", r1_time: "约1h", r1_badge: "城市沿河", r1_search: "搜索\"成都东门沿河小环线\"",
    r1_route: "<strong>路线：</strong>东门大桥→合江亭→安顺廊桥→九眼桥→望江楼→东湖公园→东篱翠湖→沙河绿道→塔子山公园→双桂公园→多宝寺→新华公园→活水公园→返回东门大桥（13个节点）",
    r1_why: "<strong>推荐理由：</strong>沿着成都东部水系的一条紧凑型城市环线，串联13个景观节点，涵盖历史桥梁、公园和寺庙。非常适合悠闲的午后骑行。",
    r2_title: "城中沿河大环线", r2_dist: "40.90 km", r2_time: "约4h17min", r2_badge: "城市沿河", r2_search: "搜索\"成都城中沿河大环线\"",
    r2_route: "<strong>路线：</strong>沙河→府河→南河环线，串联成都中心城区主要水系",
    r2_why: "<strong>推荐理由：</strong>沿着成都三条主要城市河流的景观大环线。全程40.9公里，均速9.55 km/h，是一次穿越城市水道核心区的悠闲观光骑行。",
    r3_title: "锦江绿道+绕城绿道互通环线", r3_dist: "15-25 km", r3_time: "约2-3h", r3_badge: "城市沿河", r3_search: "搜索\"锦江绕城绿道互通环线\"",
    r3_route: "<strong>路线：</strong>东湖公园→锦城公园→中和湿地公园（10个公园节点，绿道互通）",
    r3_why: "<strong>推荐理由：</strong>无缝连接锦江绿道与绕城绿道，途经10个公园节点。灵活性强，可根据体力选择15至25公里不同路段。",
    r4_title: "绕城绿道东南段：青龙湖-玉石湿地-花田湿地-白鹭湾湿地", r4_dist: "15.12 km", r4_time: "约1.5h", r4_badge: "湿地生态",
    r4_route: "<strong>路线：</strong>青龙湖湿地公园→玉石湿地公园→花田湿地→白鹭湾湿地公园",
    r4_why: "<strong>推荐理由：</strong>在成都绕城绿道东南段，15公里的温柔骑行穿越四个不同的湿地生态系统。观鸟爱好者的天堂，生物多样性丰富。",
    r5_title: "徐堰河-柏条河沿河绿道", r5_dist: "约7 km", r5_time: "约1h", r5_badge: "湿地生态", r5_search: "搜索\"徐堰河柏条河绿道\"",
    r5_route: "<strong>路线：</strong>5个湿地生态节点，串联郫都区三道堰境内约7公里生态绿道，含成都首条\"空中绿道\"（宽3.5米）",
    r5_why: "<strong>推荐理由：</strong>紧凑的7公里骑行，特色是成都首条\"空中绿道\"——一条宽3.5米的架空骑行道，悬浮于湿地之上，提供独特的观赏视角。",
    r6_title: "绕城绿道西南段：锦城湖-悦动彩林-萌宠乐园-国际非物质遗产博览园", r6_dist: "24.27 km", r6_time: "约2.5h", r6_badge: "湿地生态",
    r6_route: "<strong>路线：</strong>锦城湖公园→悦动彩林→萌宠乐园→国际非物质文化遗产博览园",
    r6_why: "<strong>推荐理由：</strong>24公里穿越绕城绿道西南段，途经七彩森林、萌宠乐园，终点抵达联合国教科文组织非物质文化遗产博览园。",
    r7_title: "青龙湖-东风渠-东安湖", r7_dist: "约30 km", r7_time: "约3h", r7_badge: "新区公园", r7_search: "搜索\"青龙湖东安湖骑行\"",
    r7_route: "<strong>路线：</strong>青龙湖湿地公园→东风渠绿道→东安湖体育公园→驿马河公园二期→龙泉山城市森林公园",
    r7_why: "<strong>推荐理由：</strong>30公里从青龙湖湿地静谧到奥运标准东安湖体育公园，终点抵达龙泉山麓。城市公园设计与自然景观的完美融合。",
    r8_title: "天府新区绿道环线骑行线（鹿溪河与天府公园）", r8_dist: "40.99 km", r8_time: "约3.5h", r8_badge: "新区公园",
    r8_route: "<strong>路线：</strong>鹿溪河生态区→天府公园→兴隆湖→科学城",
