    r11_title: "清水河-沱江河沿河绿道", r11_dist: "44.60 km", r11_time: "约2h10min", r11_badge: "乡村绿道", r11_search: "搜索\"清水河沱江河绿道\"",
    r11_route: "<strong>路线：</strong>清水河→沱江河沿河绿道，郫都区境内",
    r11_why: "<strong>推荐理由：</strong>44.6公里的河边骑行，均速达20.51 km/h——乡村类中最快节奏的路线。沿两条河流穿越郫都区风景如画的乡村。",
    r12_title: "温江绿道大环线：北林绿道", r12_dist: "52.51 km", r12_time: "约4h45min", r12_badge: "乡村绿道", r12_search: "搜索\"温江北林绿道\"",
    r12_route: "<strong>路线：</strong>温江北林绿道大环线，穿越温江乡村田园风光",
    r12_why: "<strong>推荐理由：</strong>最长乡村路线，52.5公里、463米爬升。真正的进阶级挑战，穿越温江北林绿道，展现广阔的田园风光和竹林美景。",
    r13_title: "锦江绿道：蜀绣公园-都江堰", r13_dist: "58.52 km", r13_time: "约6h13min", r13_badge: "长途挑战", r13_search: "搜索\"锦江绿道蜀绣到都江堰\"",
    r13_route: "<strong>路线：</strong>蜀绣公园→锦江绿道北段→都江堰景区，沿锦江溯流而上",
    r13_why: "<strong>推荐理由：</strong>终极挑战——58.5公里沿锦江逆流而上，从蜀绣公园骑行至联合国教科文组织世界遗产都江堰水利工程。穿越历史，从成都平原到青藏高原山麓。",
    r14_title: "邛崃幸福崃道骑行线", r14_dist: "12.48 km", r14_time: "约1h", r14_badge: "特色主题",
    r14_route: "<strong>路线：</strong>邛窑国家考古遗址公园→茶兰林盘→宝马骑行公园→平乐古镇",
    r14_why: "<strong>推荐理由：</strong>中国首条旅游专用自行车高速公路！12.5公里彩色沥青路面，专为骑行者建造。从考古公园穿越茶园和竹林，抵达历史悠久的平乐古镇。",
