    sb_upgrade_extra: '另外还有<strong style="color:var(--accent2);">共享电单车</strong>（⚡ 电助力，长途绿道骑行首选！）和<strong style="color:#c2185b;">紫色粉色浪漫限定共享单车</strong> 💜💗——超可爱，拍照打卡绝佳！',
    sb_tip4: "工作日、周末和节假日价格可能不同——骑行前请查看App",
    metro_bike_title: "地铁+共享单车：成都出行黄金组合", metro_bike_desc: "成都地铁已开通14+条线路，覆盖全城。坐空调地铁避开酷暑和拥堵，出站即扫共享单车直达景点门口——夏日清凉出行的不二之选！", metro_step1_title: "第一步：坐地铁", metro_step1_desc: "坐空调地铁避开炎热街道。成都地铁覆盖所有主要区域。", metro_step2_title: "第二步：扫辆单车", metro_step2_desc: "出站即扫共享单车。美团/哈啰/青桔遍布各大地铁口。", metro_step3_title: "第三步：清爽抵达", metro_step3_desc: "最后1-3公里骑行直达景点门口。不出汗、不愁停车！", metro_tip1: '❄️ <strong style="color:var(--ink);">空调避难所：</strong>地铁车厢全程空调——夏天穿越城市最凉爽的方式（外面30–35°C！）', metro_tip2: '💳 <strong style="color:var(--ink);">一码通行：</strong>支付宝乘车码既能刷地铁闸机又能扫共享单车——无需分开购票', metro_tip3: '🗺 <strong style="color:var(--ink);">出口即单车：</strong>成都每个地铁口的A–D出口都有共享单车停放——无需走远路', metro_tip4: '🌳 <strong style="color:var(--ink);">绿道直达站：</strong>1、5、6、18号线均连接天府绿道枢纽——出站直接骑上绿道！', metro_tip5: '🕐 <strong style="color:var(--ink);">运营时间：</strong>每日6:00–23:30。规划好返程——末班车时间因线路和站点而异', metro_tip6: '💡 <strong style="color:var(--ink);">进阶玩法：</strong>地铁坐到城市边缘→骑共享单车深入田园。舒适与冒险兼得！',
