    nav_safety: "Sécurité", nav_events: "Événements", nav_links: "Liens", nav_red: "Suivez-nous",
    hero_badge: "🚲 Découvrez Chengdu à vélo", hero_title: "Parcourez Chengdu comme un local",
    hero_sub: "Le guide ultime pour explorer les voies vertes, les ruelles cachées et la campagne de Chengdu — depuis la selle d'un vélo.",
    hero_btn1: "🚴 Explorer les parcours", hero_btn2: "🚲 Louer un vélo",
    why_title: "Pourquoi faire du vélo à Chengdu ?", why_sub: "L'une des villes les plus cyclables de Chine, avec des voies vertes de classe mondiale et une culture cycliste dynamique.",
    stat1: "Voie verte Tianfu — la plus longue boucle cyclable urbaine au monde, traversant 78 ponts emblématiques",
    stat2: "Curated cycling routes covering city rivers, wetlands, parks, countryside, and long-distance challenges",
