    rental_title: "Guide de location de vélos", rental_sub: "Deux façons d'obtenir un vélo : vélos partagés pour les trajets rapides, ou magasins de location pour VTT, vélos de route et équipement complet.",
    rental_shared_title: "Vélos partagés — Rapide et économique", rental_shared_desc: "Vélos à scanner disponibles partout à Chengdu. Idéal pour les courts trajets urbains et les excursions sur la voie verte.",
    tbl_penalty: "Pénalité",
