    route_map_amap: '📍 Navigation Amap',
    stat2: '14',
    stat2_label: 'Parcours cyclistes sélectionnés, du loisir débutant au défi longue distance, couvrant tout Chengdu par thème',
    routes_title: 'Guide des parcours cyclistes',
    routes_sub: '14+ parcours sélectionnés couvrant les berges urbaines, l\'écologie des zones humides, les parcs des nouveaux districts, les voies vertes rurales, les défis longue distance et les thèmes spéciaux, avec identifiants de roadbook pour importation en un clic',
    r1_title: 'Boucle fluviale de la Porte Est',
    r1_dist: '8-12 km',
    r1_time: '~1 h',
    r1_diff: 'Débutant',
    r1_stars: '★☆☆☆☆',
    r1_route: 'Pont Dongmen → Pavillon Hejiang → Pont Anshun → Pont Jiuyan → Tour Wangjiang → Parc du Lac Est → Dongli Cuihu → Voie verte de Shahe → Parc Tazishan → Parc Shuanggui → Temple Duobao → Parc Xinhua → Parc Living Water → retour au Pont Dongmen',
    r1_why: 'Reliant plusieurs sites emblématiques de la Porte Est de Chengdu, le choix idéal pour les balades courtes, parfait pour les familles et les débutants, avec 13 points d\'intérêt',
    r1_tip1: 'Passez par le Pavillon Hejiang pour admirer la confluence unique des rivières Fuhe et Nanhe',
