    hero_badge: "🚲 Descubre Chengdu en dos ruedas", hero_title: "Recorre Chengdu como un local",
    hero_sub: "La guía definitiva para explorar las vías verdes, callejones escondidos y el campo de Chengdu — desde el sillín de una bicicleta.",
    hero_btn1: "🚴 Explorar rutas", hero_btn2: "🚲 Alquilar una bici",
    why_title: "¿Por qué pedalear en Chengdu?", why_sub: "Una de las ciudades más amigables con la bicicleta en China, con vías verdes de clase mundial y una vibrante cultura ciclista.",
    stat1: "Vía Verde Tianfu — el circuito ciclista urbano más largo del mundo, cruzando 78 puentes icónicos",
    stat2: "Curated cycling routes covering city rivers, wetlands, parks, countryside, and long-distance challenges",
