    sb_feat6: "🦠 Manillar antibacteriano",
    sb_upgrade_extra: '¡También busca las <strong style="color:var(--accent2);">Bicis eléctricas compartidas</strong> (⚡ pedaleo asistido) y las <strong style="color:#c2185b;">Bicis edición limitada púrpura &amp; rosa</strong> 💜💗 — ¡súper lindas para fotos!',
    sb_tip4: "Los precios pueden variar entre días laborables, fines de semana y festivos — consulta la app antes de andar",
    metro_bike_title: "Metro + Bici compartida: El combo definitivo en Chengdu", metro_bike_desc: "El metro de Chengdu tiene más de 14 líneas que cubren toda la ciudad. Toma el metro con aire acondicionado para evitar el calor, luego toma una bici compartida en la salida. ¡La estrategia perfecta de verano!", metro_step1_title: "Paso 1: Toma el metro", metro_step1_desc: "Toma el metro con aire acondicionado para evitar las calles calurosas. Cubre todas las zonas principales.", metro_step2_title: "Paso 2: Toma una bici", metro_step2_desc: "Escanea una bici compartida justo afuera de la estación. Hay bicis Meituan/Hello/Qingju por todas partes.", metro_step3_title: "Paso 3: Llega fresco", metro_step3_desc: "Recorre los últimos 1–3 km hasta la entrada del lugar. ¡Sin sudar, sin problemas de estacionamiento!", metro_tip1: '❄️ <strong style="color:var(--ink);">Escape con AC:</strong> Los vagones tienen aire acondicionado — la forma más fresca de cruzar la ciudad en verano (¡30–35°C afuera!)', metro_tip2: '💳 <strong style="color:var(--ink);">Una app para todo:</strong> El código QR de Alipay funciona para el metro y las bicis — sin billetes separados', metro_tip3: '🗺 <strong style="color:var(--ink);">Bicis en cada salida:</strong> Las estaciones de metro siempre tienen bicis en las salidas A–D — nunca caminarás lejos', metro_tip4: '🌳 <strong style="color:var(--ink);">Estaciones Greenway:</strong> Las líneas 1, 5, 6, 18 conectan con los hubs de Tianfu Greenway — ¡pedalea directo a la vía verde!', metro_tip5: '🕐 <strong style="color:var(--ink);">Horario del metro:</strong> 6:00–23:30 diario. Planea tu regreso — el último tren varía según la línea', metro_tip6: '💡 <strong style="color:var(--ink);">Movida pro:</strong> Metro hasta el borde de la ciudad → bici al campo. ¡Lo mejor de ambos mundos!',
sb_rules_title: "📋 Guía esencial de bicis compartidas",
    sb_rules_map: "🗺 Reglas del mapa",
    sb_rules_parking: "Estacionamiento designado:",
    sb_rules_parking_desc: "Estaciona en zonas designadas. La bici debe estar vertical dentro de las líneas, rueda delantera en la misma dirección.",
    sb_rules_pzone: "Zona de estacionamiento (Punto P):",
    sb_rules_pzone_desc: 'Los iconos azules "P" en el mapa indican zonas de devolución válidas. Abre el mapa para encontrar el punto P más cercano.',
    sb_rules_nozone: "Zona prohibida:",
    sb_rules_nozone_desc: "Las zonas rojas en el mapa = estacionamiento prohibido. Estacionar aquí genera multas (¥1–20). ¡Nunca estaciones en zona roja!",
    sb_rules_find: "Cómo encontrar estacionamiento:",
    sb_rules_find_desc: "Abre el mapa de la app — los puntos P azules son tus objetivos. Siempre verifica la disponibilidad cerca de tu destino antes de salir.",
    sb_rules_lock: "🔒 Bloqueo y devolución",
    sb_rules_unlock: "Cómo desbloquear:",
    sb_rules_unlock_desc: "① Escanea el código QR en el cuadro, o ② Ingresa manualmente el número del vehículo. Asegúrate de que Bluetooth esté activado.",
    sb_rules_unlock_fail: "Fallo al escanear:",
    sb_rules_unlock_fail_desc: "Verifica: red móvil estable, Bluetooth activado, código QR limpio. Intenta reiniciar la app.",
    sb_rules_templock: "Bloqueo temporal:",
    sb_rules_templock_desc: 'Toca "Bloqueo temporal" en la app durante el viaje. Nota: la facturación continúa mientras está bloqueado temporalmente.',
    sb_rules_lock_how: "Cómo bloquear y devolver:",
    sb_rules_lock_how_desc: '① Estaciona la bici verticalmente, ② Cierra el candado inteligente hasta oír un "bip", ③ Espera que la app muestre "Devolución exitosa".',
    sb_rules_lock_fail: "No se puede bloquear:",
    sb_rules_lock_fail_desc: "Posibles razones: no está en zona P, bici mal estacionada, mala señal, o fallo del candado. Muévete a un punto P y reintenta.",
    sb_rules_forgot: "Olvidaste bloquear:",
    sb_rules_forgot_desc: "¡Contacta al servicio al cliente inmediatamente! Proporciona el número del vehículo y ubicación — pueden bloquear remotamente.",
    sb_rules_order_end: "Viaje no termina después de bloquear:",
    sb_rules_order_end_desc: "Espera 1–2 minutos. Si el viaje aún no ha terminado, reinicia la app o contacta al soporte.",
    sb_rules_phone_dead: "Teléfono sin batería / perdido:",
    sb_rules_phone_dead_desc: "Pide prestado un teléfono para iniciar sesión, o contacta al soporte con tu información de identidad.",
    sb_rules_fault: "🔧 Avería del vehículo",
    sb_rules_fault_ride: "Avería durante el viaje:",
    sb_rules_fault_ride_desc: 'Detente inmediatamente en un lugar seguro. Toca "Reportar reparación" en la app, o contacta al soporte.',
    sb_rules_fault_report: "Proceso de reporte de reparación:",
    sb_rules_fault_report_desc: '① Toca "Reportar" → ② Selecciona el tipo de fallo y toma una foto → ③ Envía y cambia de bici. Los costos pueden ser apelados.',
    sb_rules_appeal: "Apelación de tarifas:",
    sb_rules_appeal_desc: 'Ve a "Mi cuenta" → "Historial" → selecciona el pedido → "Apelar tarifa" → completa el motivo. Se procesa en 1–3 días hábiles.',
    sb_rules_credit: "Puntuación de crédito:",
    sb_rules_credit_desc: "Regula el comportamiento de uso. El estacionamiento ilegal descuenta puntos y puede afectar tu acceso al servicio.",
    sb_rules_support: "Atención al cliente:",
    sb_rules_support_desc: 'En la app: "Mi cuenta" → "Centro de ayuda". Cada app tiene línea directa. Soporte 24/7.',
