    ali_step1: "Descarga \"Alipay\" desde App Store / Google Play", ali_step2: "Regístrate con tu número de teléfono (números internacionales aceptados)", ali_step3: "Ve a \"Yo\" → \"Tarjetas bancarias\" → Añade tu Visa/Mastercard", ali_step4: "Verifica tu identidad con foto del pasaporte (~5 min)", ali_step5: "¡Listo! Escanea códigos QR para pagar, desbloquear bicis y más",
