    qt_title: "Consejos rápidos",
    qt1: "Ambas apps funcionan con tarjetas extranjeras (Visa, Mastercard, Amex)", qt2: "Límite de transacción: ~¥3.000 por transacción para tarjetas extranjeras", qt3: "Configura al menos 1 app antes de llegar a Chengdu", qt4: "Necesitas una de estas para desbloquear bicis — sin app, no hay bici", qt5: "Alipay es recomendado para extranjeros por su soporte en inglés", qt6: "Ambas apps también funcionan para: metro, autobús, taxis, comida a domicilio, compras",
    safety_title: "Consejos de seguridad y etiqueta ciclista", safety_sub: "Mantente seguro y respetuoso en las vías ciclistas compartidas de Chengdu.",
    rule1_title: "Límite de velocidad", rule1_desc: "20 km/h máximo en vías verdes. Reduce la velocidad cerca de niños y peatones.",
    rule2_title: "Mantén la derecha", rule2_desc: "Circula siempre por la derecha. Adelanta por la izquierda con timbre o aviso verbal.",
    rule3_title: "Guía del casco", rule3_desc: "Se recomienda el casco para bicis compartidas, de carretera y de montaña. El casco es obligatorio para bicis eléctricas.",
    rule4_title: "No en paralelo", rule4_desc: "No circules en paralelo. Mantén el camino libre para ciclistas más rápidos y peatones.",
    rule5_title: "Protección solar", rule5_desc: "Los veranos en Chengdu son húmedos (30–35°C). Protector solar, gafas y agua son esenciales.",
    rule6_title: "Alerta de lluvia", rule6_desc: "Tormentas de verano frecuentes. Las vías verdes resbalan tras la lluvia — circula con precaución.",
    rule7_title: "Batería del teléfono", rule7_desc: "Tu teléfono es tu mapa, pago y llave de la bici. Lleva una batería externa para rutas largas.",
    rule8_title: "Emergencia", rule8_desc: "Policía: 110 | Ambulancia: 120 | Línea policial en inglés: 12367",
    events_title: "Próximos eventos y actividades ciclistas", events_sub: "Únete a eventos, carreras y salidas en grupo. Sigue nuestra cuenta RED para actualizaciones.",
    ev1_title: "🌿 Carrera Internacional de Ciclismo Vía Verde Tianfu", ev1_desc: "Evento anual — 16 equipos internacionales en la vía verde de 100 km. Sesiones amateur disponibles.",
    ev2_month: "Cada", ev2_day: "Sáb", ev2_title: "🚴 Salida grupal WeCycle", ev2_desc: "Salida semanal del sábado por la mañana. Inglés-friendly. 30–50 km, terreno mixto. Encuentro en WeCycle MixC a las 8:00.",
    ev3_month: "Cada", ev3_day: "Dom", ev3_title: "🐼 Salida social Ruta Panda", ev3_desc: "Paseo informal del domingo por la tarde siguiendo la ruta «dibuja un panda». 12,7 km, ritmo fácil. Consulta nuestro RED.",
    ev4_month: "Pendiente", ev4_title: "🎉 Más eventos próximamente", ev4_desc: "Salidas nocturnas, luna llena en la vía verde, tours de ciclismo + fondue, y salidas fotográficas. Suscríbete a nuestro RED.",
