    routes_sub: '14+ rutas seleccionadas que cubren riberas urbanas, ecología de humedales, parques de nuevos distritos, vías verdes rurales, desafíos de larga distancia y temas especiales, con IDs de libro de ruta para importar con un clic',
    r1_title: 'Circuito fluvial de la Puerta Este',
    r1_dist: '8-12 km',
    r1_time: '~1 h',
    r1_diff: 'Principiante',
    r1_stars: '★☆☆☆☆',
    r1_route: 'Puente Dongmen → Pabellón Hejiang → Puente Anshun → Puente Jiuyan → Torre Wangjiang → Parque del Lago Este → Dongli Cuihu → Vía Verde Shahe → Parque Tazishan → Parque Shuanggui → Templo Duobao → Parque Xinhua → Parque Living Water → regreso al Puente Dongmen',
    r1_why: 'Conectando múltiples lugares emblemáticos de la Puerta Este de Chengdu, la mejor opción para paseos cortos, perfecto para familias y principiantes, con 13 puntos de referencia',
    r1_tip1: 'Pase por el Pabellón Hejiang para admirar la confluencia única de los ríos Fuhe y Nanhe',
    r1_tip2: 'El Puente Anshun es un puente antiguo emblemático de Chengdu, especialmente encantador por la noche, perfecto para paseos nocturnos',
    r1_tip3: 'Alta cobertura de vías verdes, excelente seguridad, ideal para familias con múltiples parques para descansar',
    r1_route_book: 'Jike Cycling 10129990 (pendiente), busque \'East Gate Riverside Loop\' en Blackbird/Xingzhe/Strava',
    r2_title: 'Gran circuito fluvial del centro de la ciudad',
    r2_dist: '40,90 km',
    r2_time: '~4h17min',
    r2_diff: 'Principiante-Intermedio',
    r2_stars: '★★☆☆☆',
    r2_route: 'Río Shahe → Río Fuhe → Río Nanhe, conectando los principales sistemas hídricos del centro de Chengdu',
    r2_why: 'El gran circuito de sistemas hídricos del centro de Chengdu, cubriendo los tres principales sistemas fluviales en un solo recorrido',
    r2_tip1: 'Un desafío de media a larga distancia, adecuado para ciclistas con experiencia; lleve suficientes provisiones',
    r2_tip2: 'Pasa por múltiples parques urbanos donde puede descansar y reabastecerse',
    r2_tip3: 'Comience temprano por la mañana para evitar el tráfico, sintiendo el pulso urbano de Chengdu al amanecer',
    r2_route_book: 'Busque \'Central City Riverside Grand Loop\' en Blackbird/Xingzhe/Strava',
    r3_title: 'Circuito de intercambio Jinjiang-Carretera de Circunvalación',
    r3_dist: '15-25 km',
    r3_time: '~2-3 h',
    r3_diff: 'Principiante-Intermedio',
    r3_stars: '★★☆☆☆',
    r3_route: 'Parque Donghu → Parque Jincheng → Parque de Humedales Zhonghe (10 nodos de parque, intercambio de vías verdes)',
    r3_why: 'Intercambio de vías verdes ingeniosamente diseñado que conecta 10 nodos de parque, longitud de ruta flexible',
    r3_tip1: 'La vía verde se interconecta con la vía verde de la carretera de circunvalación, ofreciendo opciones flexibles',
    r3_tip2: 'El Parque de Humedales Zhonghe es un excelente lugar para observar aves, con numerosas aves migratorias',
    r3_tip3: 'El Parque Jincheng cuenta con instalaciones bien desarrolladas, ideal para descansar y reabastecerse a mitad del recorrido',
    r3_route_book: 'Busque \'Jinjiang-Ring Road Greenway Interchange Loop\' en Blackbird/Xingzhe/Strava',
    r4_title: 'Anillo SE: Lago Qinglong - Humedal Bailuwan',
    r4_dist: '15,12 km',
    r4_time: '~1,5 h',
    r4_diff: 'Principiante',
    r4_stars: '★☆☆☆☆',
    r4_route: 'Parque de Humedales del Lago Qinglong → Parque de Humedales Yushi → Humedal Huatian → Parque de Humedales Bailuwan',
    r4_why: 'La mejor sección sureste de la Vía Verde del Anillo, conectando cuatro grandes parques de humedales, completamente plano',
    r4_tip1: 'El Lago Qinglong es el parque de humedales urbano más grande de Chengdu, la niebla matutina en el lago es de ensueño',
    r4_tip2: 'El Humedal Bailuwan es famoso por su hábitat de garzas, una visita obligada para observadores de aves',
    r4_tip3: 'Terreno completamente plano, excelentes condiciones de la carretera, señalización clara, ideal para principiantes y familias',
    r4_route_book: 'Jike Cycling 10129983',
