    r5_stars: '★★☆☆☆',
    r5_route: '5 nodos ecológicos de humedales a lo largo de ~7 km de vía verde ecológica en Sandaoyan, Distrito de Pidu, incluyendo la primera \'vía verde aérea\' de Chengdu (3,5 m de ancho)',
    r5_why: 'La primera \'vía verde aérea\' de Chengdu que ofrece una experiencia ciclista elevada única, una ruta corta pero premium',
    r5_tip1: 'La vía verde aérea tiene 3,5 m de ancho con vistas panorámicas, muy fotogénica',
    r5_tip2: 'Sandaoyan es una zona de protección de fuentes de agua de Chengdu, con agua cristalina y aire fresco',
    r5_tip3: 'Corta distancia, baja intensidad, perfecto para paseos tranquilos, apto para todas las edades',
    r5_route_book: 'Busque \'Xuyan-Baitiao Riverside Greenway\' en Blackbird/Xingzhe/Strava',
