    hero_sub: "청두의 그린웨이, 숨겨진 골목과 시골 풍경을 자전거로 탐험하는 최고의 가이드.",
    hero_btn1: "🚴 루트 탐색", hero_btn2: "🚲 자전거 대여",
    why_title: "왜 청두에서 자전거를 타야 할까요?", why_sub: "중국에서 가장 자전거 친화적인 도시 중 하나로, 세계적 수준의 그린웨이와 활기찬 자전거 문화를 자랑합니다.",
    stat1: "톈푸 그린웨이 — 78개의 상징적인 다리를 가로지르는 세계 최장 도시 자전거 루프",
