    r14_why: "<strong>Why this route:</strong> China's first tourism-only dedicated bicycle highway! A 12.5 km stretch of colored asphalt built exclusively for cyclists. Ride from an archaeological park through tea fields and bamboo forests to the historic Pingle Ancient Town.",
