    sb_upgrade_extra: '<strong style="color:var(--accent2);">電動シェアサイクル</strong>（⚡ 電動アシスト、長距離ライドに最適！）や<strong style="color:#c2185b;">限定版パープル＆ピンクバイク</strong> 💜💗も要チェック — 写真映え抜群！',
    sb_tip4: "平日、週末、祝日で料金が異なる場合があります — 乗車前にアプリで確認してください",
    metro_bike_title: "地下鉄＋シェアサイクル：成都の究極コンボ", metro_bike_desc: "成都の地下鉄は14路線以上で市内全域をカバー。冷房の効いた地下鉄で暑さと渋滞を回避し、駅出口でシェアサイクルに乗って目的地までラクラク到着。夏にぴったりの作戦です！", metro_step1_title: "ステップ1：地下鉄に乗る", metro_step1_desc: "冷房の効いた地下鉄で暑い街をスキップ。成都の地下鉄は主要エリアをすべてカバー。", metro_step2_title: "ステップ2：自転車をゲット", metro_step2_desc: "駅の出口すぐでシェアサイクルをスキャン。美団/ハロー/青桔はどこにでもあります。", metro_step3_title: "ステップ3：爽快に到着", metro_step3_desc: "最後の1～3kmを走って観光スポットの入口へ。汗もかかず、駐車の心配もなし！", metro_tip1: '❄️ <strong style="color:var(--ink);">冷房避難：</strong>車内は完全冷房 — 夏の街を横断する最も涼しい方法（外は30–35°C！）', metro_tip2: '💳 <strong style="color:var(--ink);">1アプリで全部：</strong>アリペイのQRコードで地下鉄改札もシェアサイクルもOK — 別々の切符不要', metro_tip3: '🗺 <strong style="color:var(--ink);">各出口に自転車：</strong>成都の地下鉄駅のA–D出口にはいつもシェアサイクルあり — 遠くまで歩く必要なし', metro_tip4: '🌳 <strong style="color:var(--ink);">緑道直結駅：</strong>1、5、6、18号線は天府緑道ハブに接続 — 駅から直接緑道へ！', metro_tip5: '🕐 <strong style="color:var(--ink);">営業時間：</strong>毎日6:00–23:30。帰りの計画を——終電は路線と駅によって異なります', metro_tip6: '💡 <strong style="color:var(--ink);">上級テク：</strong>地下鉄で街の端まで→自転車で田園へ。快適さと冒険の両方を！',
sb_rules_title: "📋 シェアサイクル必読ガイド",
    sb_rules_map: "🗺 マップルール",
    sb_rules_parking: "指定駐輪：",
    sb_rules_parking_desc: "指定エリア内に駐輪してください。自転車は白線内に垂直に停め、前輪の向きを他の自転車と揃えてください。",
    sb_rules_pzone: "駐輪ゾーン（Pポイント）：",
    sb_rules_pzone_desc: "アプリの地図上で青いPアイコンが表示されている場所が返却可能エリアです。アプリの地図を開いて最寄りのPポイントを探してください。",
    sb_rules_nozone: "駐輪禁止エリア：",
    sb_rules_nozone_desc: "地図上で赤く表示されるエリア＝駐輪禁止。ここに駐輪すると罰金（¥1–20）が発生します。赤いエリアには絶対に駐輪しないでください！",
    sb_rules_find: "駐輪場所の探し方：",
    sb_rules_find_desc: "アプリの地図を開く——青いPポイントが返却目標です。出発前に目的地付近の駐輪可能状況を必ず確認してください。",
    sb_rules_lock: "🔒 施錠・返却",
    sb_rules_unlock: "解錠方法：",
    sb_rules_unlock_desc: "① 車体のQRコードをスキャン、または ② アプリで車両番号を手動入力。Bluetoothがオンになっていることを確認してください。",
    sb_rules_unlock_fail: "スキャンで解錠できない：",
    sb_rules_unlock_fail_desc: "確認事項：モバイルネットワークが安定しているか、Bluetoothがオンか、QRコードが汚れていないか。アプリを再起動してみてください。",
    sb_rules_templock: "一時施錠：",
