    hero_badge: "🚲 ค้นพบเฉิงตูด้วยสองล้อ", hero_title: "ปั่นจักรยานเฉิงตูเหมือนคนท้องถิ่น",
    hero_sub: "คู่มือสุดยอดสำหรับการสำรวจกรีนเวย์ ตรอกซอกซอยที่ซ่อนอยู่ และชนบทของเฉิงตู — ทั้งหมดจากที่นั่งของจักรยาน",
