    theme1_title: "City Riverside Routes", theme2_title: "Wetland Ecological Routes", theme3_title: "New District Park Loops", theme4_title: "Countryside Greenways", theme5_title: "Long Distance Challenge", theme6_title: "Featured Theme Routes",
    diff_beginner: "Beginner Leisure", diff_beginner_plus: "Beginner-Intermediate", diff_intermediate: "Intermediate", diff_advanced: "Advanced",
