    metro_bike_title: "รถไฟใต้ดิน + จักรยาน共享: คอมโบสุดยอดแห่งเฉิงตู", metro_bike_desc: "รถไฟใต้ดินเฉิงตูมี 14+ สายครอบคลุมทั้งเมือง นั่งรถไฟใต้ดินติดแอร์หลบร้อนและรถติด แล้วปั่นจักรยาน共享จากหน้าสถานีถึงจุดหมาย กลยุทธ์หน้าร้อนที่สมบูรณ์แบบ!", metro_step1_title: "ขั้นตอนที่ 1: นั่งรถไฟใต้ดิน", metro_step1_desc: "นั่งรถไฟใต้ดินติดแอร์หลบถนนร้อน รถไฟใต้ดินเฉิงตูครอบคลุมทุกพื้นที่หลัก", metro_step2_title: "ขั้นตอนที่ 2: หยิบจักรยาน", metro_step2_desc: "สแกนจักรยาน共享หน้า station เลย Meituan/Hello/Qingju มีทุกที่", metro_step3_title: "ขั้นตอนที่ 3: ถึงแบบสดชื่น", metro_step3_desc: "ปั่น 1–3 กม. สุดท้ายถึงหน้าทางเข้า ไม่เหงื่อตก ไม่ต้องหาที่จอด!", metro_tip1: '❄️ <strong style="color:var(--ink);">หนีร้อนด้วยแอร์:</strong> ตู้รถไฟติดแอร์ทั้งขบวน — วิธีข้ามเมืองที่เย็นที่สุดในหน้าร้อน (ข้างนอก 30–35°C!)', metro_tip2: '💳 <strong style="color:var(--ink);">แอปเดียวจบ:</strong> QR code Alipay ใช้ได้ทั้งประตูรถไฟใต้ดินและจักรยาน共享 — ไม่ต้องซื้อตั๋วแยก', metro_tip3: '🗺 <strong style="color:var(--ink);">จักรยานทุกทางออก:</strong> สถานีรถไฟใต้ดินเฉิงตูมีจักรยาน共享จอดที่ทางออก A–D เสมอ — ไม่ต้องเดินไกล', metro_tip4: '🌳 <strong style="color:var(--ink);">สถานีกรีนเวย์:</strong> สาย 1, 5, 6, 18 เชื่อมต่อกับศูนย์กลาง Tianfu Greenway — ปั่นจากสถานีขึ้นกรีนเวย์ได้เลย!', metro_tip5: '🕐 <strong style="color:var(--ink);">เวลาเดินรถ:</strong> 6:00–23:30 น. ทุกวัน วางแผนขากลับ — รถเที่ยวสุดท้ายต่างกันตามสายและสถานี', metro_tip6: '💡 <strong style="color:var(--ink);">ทริคโปร:</strong> นั่งรถไฟใต้ดินไปสุดเมือง → ปั่นจักรยานสู่ชนบท ได้ทั้งความสบายและการผจญภัย!',
