    rs_tip1: "ร้านเช่ายังมีหมวกกันน็อค ถุงมือ กุญแจ และชุดซ่อม", rs_tip2: "ร้านส่วนใหญ่ต้องวางเงินมัดจำ (¥500–2000) หรือสำเนาหนังสือเดินทาง", rs_tip3: "WeCycle มีพนักงานที่พูดภาษาอังกฤษ — แนะนำสำหรับนักท่องเที่ยวต่างชาติ",
    pay_title: "คู่มือ Alipay และ WeChat สำหรับชาวต่างชาติ", pay_sub: "คุณต้องมีอย่างน้อยหนึ่งแอปนี้เพื่อปลดล็อกจักรยานแชร์และชำระเงินทุกอย่างในเฉิงตู",
    ali_step1: "ดาวน์โหลด \"Alipay\" จาก App Store / Google Play", ali_step2: "ลงทะเบียนด้วยเบอร์โทรศัพท์ของคุณ (รองรับเบอร์ต่างประเทศ)", ali_step3: "ไปที่ \"ฉัน\" → \"บัตรธนาคาร\" → เพิ่ม Visa/Mastercard ของคุณ", ali_step4: "ยืนยันตัวตนด้วยรูปถ่ายหนังสือเดินทาง (ใช้เวลาประมาณ 5 นาที)", ali_step5: "เสร็จแล้ว! สแกน QR โค้ดเพื่อชำระเงิน ปลดล็อกจักรยาน และอื่นๆ",
    ali_tip: "เคล็ดลับ:", ali_tip_text: "Alipay รองรับ UI ภาษาอังกฤษ เปิดใช้งานในการตั้งค่า → ภาษา",
    wx_step1: "ดาวน์โหลด \"WeChat\" จาก App Store / Google Play", wx_step2: "ลงทะเบียนด้วยเบอร์โทรศัพท์ของคุณ (รองรับเบอร์ต่างประเทศ)", wx_step3: "ไปที่ \"ฉัน\" → \"บริการ\" → \"กระเป๋าเงิน\" → \"บัตร\" → เพิ่ม Visa/Mastercard", wx_step4: "ยืนยันตัวตนด้วยหนังสือเดินทาง (อาจใช้เวลา 1–2 วันทำการ)", wx_step5: "เสร็จแล้ว! ใช้ \"สแกน\" เพื่อชำระเงินและปลดล็อกจักรยานแชร์",
    wx_tip: "เคล็ดลับ:", wx_tip_text: "UI ของ WeChat ส่วนใหญ่เป็นภาษาจีน ใช้ Alipay หากคุณต้องการภาษาอังกฤษ",
    qt_title: "เคล็ดลับด่วน",
