    safety_title: "เคล็ดลับความปลอดภัยและมารยาทการปั่นจักรยาน", safety_sub: "ปลอดภัยและให้เกียรติบนเส้นทางจักรยานที่ใช้ร่วมกันของเฉิงตู",
    rule1_title: "จำกัดความเร็ว", rule1_desc: "สูงสุด 20 กม./ชม. บนกรีนเวย์ ลดความเร็วใกล้เด็กและคนเดินเท้า",
    rule2_title: "ชิดขวา", rule2_desc: "ปั่นชิดขวาเสมอ แซงทางซ้ายพร้อมสั่นกระดิ่งหรือเตือนด้วยวาจา",
    rule3_title: "คู่มือหมวกกันน็อค", rule3_desc: "แนะนำให้สวมหมวกกันน็อคสำหรับจักรยานแชร์ จักรยานเสือหมอบ และจักรยานเสือภูเขา ต้องสวมหมวกกันน็อคสำหรับจักรยานไฟฟ้า",
    rule4_title: "ห้ามปั่นคู่ขนาน", rule4_desc: "อย่าปั่นสองคันคู่กัน เปิดทางให้จักรยานเร็วและคนเดินเท้า",
    rule5_title: "ป้องกันแสงแดด", rule5_desc: "ฤดูร้อนเฉิงตูชื้น (30–35°C) ครีมกันแดด แว่นกันแดด และน้ำเป็นสิ่งจำเป็น",
    rule6_title: "คำเตือนฝนตก", rule6_desc: "พายุฝนฟ้าคะนองในฤดูร้อนเป็นเรื่องปกติ กรีนเวย์อาจลื่นหลังฝนตก — ปั่นด้วยความระมัดระวัง",
