    r_landmark_why: "<strong>Почему этот маршрут:</strong> Идеальный маршрут по главным достопримечательностям Чэнду — каждая остановка обязательна к посещению. От буддийской тишины монастыря Вэньшу, через сияющую неоном телебашню 339, шопинг на Чуньси, прогулку по историческим переулкам Куаньчжай, дань почтения поэту Ду Фу, до легендарного храма Ухоу. Выбирайте любой участок по душе!",
