// i18n engine
(function() {
  var STORAGE_KEY = 'ccg_lang';
  var currentLang = localStorage.getItem(STORAGE_KEY) || 'en';

  function applyLang(lang) {
    currentLang = lang;
    localStorage.setItem(STORAGE_KEY, lang);
    var dict = I18N[lang] || I18N.en;

    // Update all elements with data-i18n
    document.querySelectorAll('[data-i18n]').forEach(function(el) {
      var key = el.getAttribute('data-i18n');
      if (dict[key]) {
        el.innerHTML = dict[key];
      }
    });

    // Update route card toggle texts for expanded cards
    document.querySelectorAll('.route-card.expanded .toggle-text').forEach(function(t) {
      t.innerHTML = dict.toggle_hide;
    });
    document.querySelectorAll('.route-card:not(.expanded) .toggle-text').forEach(function(t) {
      t.innerHTML = dict.toggle_view;
    });

    // Update lang label
    var labels = { en: 'EN', zh: '中文', fr: 'FR', es: 'ES', ko: 'KO', ja: 'JA', th: 'TH', ru: 'RU' };
    document.getElementById('langLabel').textContent = labels[lang] || 'EN';

    // Update active state in dropdown
    document.querySelectorAll('.lang-option').forEach(function(opt) {
      opt.classList.toggle('active', opt.getAttribute('data-lang') === lang);
    });

    // Update HTML lang attribute
    document.documentElement.lang = lang;
  }

  // Language option click handlers
  document.querySelectorAll('.lang-option').forEach(function(opt) {
    opt.addEventListener('click', function(e) {
      e.stopPropagation();
      var lang = this.getAttribute('data-lang');
      applyLang(lang);
      document.getElementById('langDropdown').classList.remove('show');
      document.getElementById('langBtn').classList.remove('open');
    });
  });

  // Apply saved language on load
  applyLang(currentLang);
})();